    {id="auto-short-i-long-i-five-4be63d",subject="Spelling / Handwriting",skill="short-i-long-i",prompt="Which word has the long i sound you hear in 'kite'?",answer="five",hint="Listen for the vowel that sounds like the name of the letter i.",explanation="Five has long i, like kite. Milk and spin have short i, as in sit.",choices={"milk","spin","five"},tier="current",sourceFact="Verified Grade 2 skill: Short i and long i",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:ea94e1e33ba7745c304229679407eaef675b76eab01113c2ff3ea0334c9c87d1",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-short-i-long-i-it-changes-from-short-i-to-long-i-381658",subject="Spelling / Handwriting",skill="short-i-long-i",prompt="You turn 'kit' into 'kite' by adding e. How does the i sound change?",answer="It changes from short i to long i.",hint="Say the first word and the new word. Listen to what happens in the middle.",explanation="Kit has short i. In kite, the final e is silent and helps signal the long i sound.",choices={"It stays short i.","It changes from short i to long i.","It changes from long i to short i."},tier="current",sourceFact="Verified Grade 2 skill: Short i and long i",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:ea94e1e33ba7745c304229679407eaef675b76eab01113c2ff3ea0334c9c87d1",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-short-i-long-i-mice-f1f668",subject="Spelling / Handwriting",skill="short-i-long-i",prompt="Which word rhymes with 'rice' and has the same long i sound?",answer="mice",hint="Say the example and each choice. Compare the vowel and the sounds that follow it.",explanation="Mice and rice have the same long i sound and the same ending sound. Race has long a. Miss has short i.",choices={"race","miss","mice"},tier="current",sourceFact="Verified Grade 2 skill: Short i and long i",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:ea94e1e33ba7745c304229679407eaef675b76eab01113c2ff3ea0334c9c87d1",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-short-i-long-i-replace-slide-with-swim-e2140e",subject="Spelling / Handwriting",skill="short-i-long-i",prompt="The short i group is 'lip, grin, slide'. Which change makes every word in the group have short i?",answer="Replace slide with swim.",hint="Say each word, then check how each suggested swap changes the vowel sounds.",explanation="Lip and grin already have short i. Slide has long i. Replacing it with swim gives three short i words.",choices={"Replace lip with time.","Replace slide with swim.","Replace grin with bike."},tier="current",sourceFact="Verified Grade 2 skill: Short i and long i",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:ea94e1e33ba7745c304229679407eaef675b76eab01113c2ff3ea0334c9c87d1",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-short-i-long-i-ship-and-grin-d66822",subject="Spelling / Handwriting",skill="short-i-long-i",prompt="Which pair has a short i sound in both words?",answer="ship and grin",hint="Check both words in each pair. Listen for the vowel sound you hear in 'fit'.",explanation="Ship and grin both have short i. Line and lip have different i sounds. Ride and pine both have long i.",choices={"ship and grin","line and lip","ride and pine"},tier="current",sourceFact="Verified Grade 2 skill: Short i and long i",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:ea94e1e33ba7745c304229679407eaef675b76eab01113c2ff3ea0334c9c87d1",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-short-i-long-i-sit-and-time-bb5d66",subject="Spelling / Handwriting",skill="short-i-long-i",prompt="A child says every word with the letter i has the same vowel sound. Which pair shows that the sounds can be different?",answer="sit and time",hint="Read both words in each pair. Check whether their vowel sounds match.",explanation="Sit has short i, but time has long i. Bike and five both have long i. Fish and milk both have short i.",choices={"bike and five","fish and milk","sit and time"},tier="current",sourceFact="Verified Grade 2 skill: Short i and long i",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:ea94e1e33ba7745c304229679407eaef675b76eab01113c2ff3ea0334c9c87d1",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-short-i-long-i-slim-d5a1ff",subject="Spelling / Handwriting",skill="short-i-long-i",prompt="Read: 'The slim cat ran home.' Which word has the short i sound?",answer="slim",hint="Read the choices slowly. Listen to the middle of each word.",explanation="Slim has short i, like sit. Cat has short a, and home has long o.",choices={"slim","cat","home"},tier="current",sourceFact="Verified Grade 2 skill: Short i and long i",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:ea94e1e33ba7745c304229679407eaef675b76eab01113c2ff3ea0334c9c87d1",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-short-i-long-i-smile-and-bike-have-long-i-swim-has-short-i-01b042",subject="Spelling / Handwriting",skill="short-i-long-i",prompt="A child groups 'smile' with 'bike' instead of 'swim'. Which reason matches the vowel sounds?",answer="Smile and bike have long i; swim has short i.",hint="Read the three words aloud. Group them by the sound of i, rather than their first letters.",explanation="Smile and bike have long i, the sound of the letter name. Swim has short i, as in fit. Words can share a first letter but have different vowel sounds.",choices={"Smile and bike have long i; swim has short i.","Words that start with s always have short i.","All three words use the same vowel sound."},tier="current",sourceFact="Verified Grade 2 skill: Short i and long i",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:ea94e1e33ba7745c304229679407eaef675b76eab01113c2ff3ea0334c9c87d1",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-subject-predicate-it-names-what-the-sentence-is-about-d28466",subject="Reading / ELA",skill="subject-predicate",prompt="Why is “The tall tree” the subject in “The tall tree swayed in the wind”?",answer="It names what the sentence is about.",hint="Decide whether the words name the subject or tell what it does.",explanation="A subject names who or what the sentence is about.",choices={"It names what the sentence is about.","It tells what the tree did.","It names where the action happened."},tier="current",sourceFact="Verified Grade 2 skill: Subject and predicate",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:692f816f82e2dbc30cadfc388a797fe176abb8e2c917e82797c8ab726df68348",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-subject-predicate-mia-is-the-subject-opened-the-window-is-the-predicate-28f606",subject="Reading / ELA",skill="subject-predicate",prompt="Which explanation correctly separates the subject and predicate in “Mia opened the window”?",answer="Mia is the subject; opened the window is the predicate.",hint="The subject names who or what; the predicate tells what that subject does or is.",explanation="Mia names who the sentence is about, and opened the window tells what Mia did.",choices={"Opened is the subject; Mia is the predicate.","The window is the subject; Mia opened is the predicate.","Mia is the subject; opened the window is the predicate."},tier="current",sourceFact="Verified Grade 2 skill: Subject and predicate",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:692f816f82e2dbc30cadfc388a797fe176abb8e2c917e82797c8ab726df68348",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-subject-predicate-my-little-brother-2af298",subject="Reading / ELA",skill="subject-predicate",prompt="In “My little brother builds a tower,” which words are the subject?",answer="My little brother",hint="Ask who is doing the action.",explanation="The subject tells who the sentence is about.",choices={"My little brother","builds a tower","a tower"},tier="current",sourceFact="Verified Grade 2 skill: Subject and predicate",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:692f816f82e2dbc30cadfc388a797fe176abb8e2c917e82797c8ab726df68348",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-subject-predicate-our-class-read-a-new-book-df7483",subject="Reading / ELA",skill="subject-predicate",prompt="Which sentence is correctly split into subject and predicate?",answer="Our class | read a new book.",hint="Keep all the subject words together, then all the words telling what the subject does.",explanation="Our class is the complete subject, and read a new book is the predicate.",choices={"Read a | new book our class.","Our class | read a new book.","A new book | our class read."},tier="current",sourceFact="Verified Grade 2 skill: Subject and predicate",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:692f816f82e2dbc30cadfc388a797fe176abb8e2c917e82797c8ab726df68348",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-subject-predicate-sing-in-the-tree-741dd3",subject="Reading / ELA",skill="subject-predicate",prompt="In the sentence “The birds sing in the tree,” which words are the predicate?",answer="sing in the tree",hint="First find the subject, then choose the words that tell what it does.",explanation="The predicate tells what the subject does: the birds sing in the tree.",choices={"The birds","sing in the tree","the tree"},tier="current",sourceFact="Verified Grade 2 skill: Subject and predicate",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:692f816f82e2dbc30cadfc388a797fe176abb8e2c917e82797c8ab726df68348",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-subject-predicate-stopped-by-the-school-d4895a",subject="Reading / ELA",skill="subject-predicate",prompt="In “The yellow bus stopped by the school,” which words are the predicate?",answer="stopped by the school",hint="Find the action and the words that go with it.",explanation="The predicate tells what the yellow bus did.",choices={"The yellow bus","stopped by the school","the school"},tier="current",sourceFact="Verified Grade 2 skill: Subject and predicate",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:692f816f82e2dbc30cadfc388a797fe176abb8e2c917e82797c8ab726df68348",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-subject-predicate-subject-the-rabbit-predicate-hopped-across-the-yard-18d487",subject="Reading / ELA",skill="subject-predicate",prompt="Which pair correctly labels the parts of “The rabbit hopped across the yard”?",answer="subject: The rabbit; predicate: hopped across the yard",hint="Split the sentence into who or what, then what that subject does.",explanation="The rabbit names who the sentence is about; hopped across the yard tells what it did.",choices={"subject: hopped; predicate: The rabbit","subject: the yard; predicate: The rabbit hopped","subject: The rabbit; predicate: hopped across the yard"},tier="current",sourceFact="Verified Grade 2 skill: Subject and predicate",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:692f816f82e2dbc30cadfc388a797fe176abb8e2c917e82797c8ab726df68348",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-subject-predicate-the-brown-puppy-1989e0",subject="Reading / ELA",skill="subject-predicate",prompt="In the sentence “The brown puppy chased the ball,” which words are the subject?",answer="The brown puppy",hint="Find who or what is doing the action.",explanation="The subject names who or what the sentence is about: the brown puppy.",choices={"chased the ball","the ball","The brown puppy"},tier="current",sourceFact="Verified Grade 2 skill: Subject and predicate",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="7e2def2720b013f7186beb750b49fac43104855256d7550f7617d7fc3b3cf331",["evidenceHash"]="sha256:692f816f82e2dbc30cadfc388a797fe176abb8e2c917e82797c8ab726df68348",["sourceUrl"]="https://sites.google.com/view/abvmgr2/tests"},priority=1},
    {id="auto-suffix-ed-ing-both-keep-the-base-action-jump-and-add-an-ending-70761f",subject="Reading / ELA",skill="suffix-ed-ing",prompt="How are “jumped” and “jumping” alike?",answer="Both keep the base action jump and add an ending.",hint="Find the unchanged base word.",explanation="Both words keep the base word jump while changing how the action is described.",choices={"Both mean the action happened yesterday.","Both keep the base action jump and add an ending.","Both are plural nouns."},tier="current",sourceFact="Verified Grade 2 skill: Adding -ed and -ing",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="599222b635e54ad8e45114cef10161280df9dbae2341aeda342f985e1133b4b9",["evidenceHash"]="sha256:1a9de1d880eb04b2584fb7583f56f3f463d9d8e1ac9274f96c5bc5b5da7479ec",["sourceUrl"]="https://sites.google.com/view/abvmgr2/reading-work"},priority=1},
    {id="auto-suffix-ed-ing-ed-helps-show-the-action-already-happened-1abc05",subject="Reading / ELA",skill="suffix-ed-ing",prompt="Why does “walked” fit “We walked home yesterday”?",answer="-ed helps show the action already happened.",hint="Use the time clue yesterday.",explanation="The -ed ending commonly marks a completed past action.",choices={"-ed helps show the action already happened.","-ed makes the word name a person.","-ed always means the action is happening now."},tier="current",sourceFact="Verified Grade 2 skill: Adding -ed and -ing",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="599222b635e54ad8e45114cef10161280df9dbae2341aeda342f985e1133b4b9",["evidenceHash"]="sha256:1a9de1d880eb04b2584fb7583f56f3f463d9d8e1ac9274f96c5bc5b5da7479ec",["sourceUrl"]="https://sites.google.com/view/abvmgr2/reading-work"},priority=1},
    {id="auto-suffix-ed-ing-jumped-1d568a",subject="Reading / ELA",skill="suffix-ed-ing",prompt="Which word correctly adds -ed to “jump”?",answer="jumped",hint="Keep the base word and add -ed.",explanation="Jump + ed makes jumped.",choices={"jumped","jumpeded","jumpsed"},tier="current",sourceFact="Verified Grade 2 skill: Adding -ed and -ing",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="599222b635e54ad8e45114cef10161280df9dbae2341aeda342f985e1133b4b9",["evidenceHash"]="sha256:1a9de1d880eb04b2584fb7583f56f3f463d9d8e1ac9274f96c5bc5b5da7479ec",["sourceUrl"]="https://sites.google.com/view/abvmgr2/reading-work"},priority=1},
    {id="auto-suffix-ed-ing-jumping-93a2ed",subject="Reading / ELA",skill="suffix-ed-ing",prompt="Which word correctly completes the sentence “Mia is ___ at recess right now”?",answer="jumping",hint="Use the time clue in the sentence to choose the ending.",explanation="The words “right now” show that the action is happening, so jumping fits.",choices={"jumped","jumping","jumps"},tier="current",sourceFact="Verified Grade 2 skill: Adding -ed and -ing",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="599222b635e54ad8e45114cef10161280df9dbae2341aeda342f985e1133b4b9",["evidenceHash"]="sha256:1a9de1d880eb04b2584fb7583f56f3f463d9d8e1ac9274f96c5bc5b5da7479ec",["sourceUrl"]="https://sites.google.com/view/abvmgr2/reading-work"},priority=1},
    {id="auto-suffix-ed-ing-jumping-b8f13d",subject="Reading / ELA",skill="suffix-ed-ing",prompt="Which word correctly adds -ing to the base word jump?",answer="jumping",hint="Keep the base word jump and add the ending -ing.",explanation="Jump + ing makes jumping.",choices={"jumping","jumpeding","jumpsing"},tier="current",sourceFact="Verified Grade 2 skill: Adding -ed and -ing",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="599222b635e54ad8e45114cef10161280df9dbae2341aeda342f985e1133b4b9",["evidenceHash"]="sha256:1a9de1d880eb04b2584fb7583f56f3f463d9d8e1ac9274f96c5bc5b5da7479ec",["sourceUrl"]="https://sites.google.com/view/abvmgr2/reading-work"},priority=1},
    {id="auto-suffix-ed-ing-looking-7a3e7f",subject="Reading / ELA",skill="suffix-ed-ing",prompt="Which word completes “We are ___ at the picture right now”?",answer="looking",hint="Use the time clue.",explanation="Right now shows the action is happening, so looking fits.",choices={"looked","looking","looks"},tier="current",sourceFact="Verified Grade 2 skill: Adding -ed and -ing",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="599222b635e54ad8e45114cef10161280df9dbae2341aeda342f985e1133b4b9",["evidenceHash"]="sha256:1a9de1d880eb04b2584fb7583f56f3f463d9d8e1ac9274f96c5bc5b5da7479ec",["sourceUrl"]="https://sites.google.com/view/abvmgr2/reading-work"},priority=1},
    {id="auto-suffix-ed-ing-played-c378c7",subject="Reading / ELA",skill="suffix-ed-ing",prompt="Which word best completes “Yesterday we ___ at recess”?",answer="played",hint="Use the word yesterday.",explanation="Yesterday signals a completed past action, so played fits.",choices={"playing","plays","played"},tier="current",sourceFact="Verified Grade 2 skill: Adding -ed and -ing",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="599222b635e54ad8e45114cef10161280df9dbae2341aeda342f985e1133b4b9",["evidenceHash"]="sha256:1a9de1d880eb04b2584fb7583f56f3f463d9d8e1ac9274f96c5bc5b5da7479ec",["sourceUrl"]="https://sites.google.com/view/abvmgr2/reading-work"},priority=1},
    {id="auto-suffix-ed-ing-when-or-how-the-action-is-happening-8c08b0",subject="Reading / ELA",skill="suffix-ed-ing",prompt="What does adding -ed or -ing usually help show about an action word?",answer="When or how the action is happening",hint="Compare a word such as played with playing.",explanation="The endings -ed and -ing change how the action is described while keeping the base action idea.",choices={"That the word names a person","That the base word has no meaning","When or how the action is happening"},tier="current",sourceFact="Verified Grade 2 skill: Adding -ed and -ing",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="599222b635e54ad8e45114cef10161280df9dbae2341aeda342f985e1133b4b9",["evidenceHash"]="sha256:1a9de1d880eb04b2584fb7583f56f3f463d9d8e1ac9274f96c5bc5b5da7479ec",["sourceUrl"]="https://sites.google.com/view/abvmgr2/reading-work"},priority=1},
    {id="auto-theme-helping-others-is-a-kind-choice-fad032",subject="Reading / ELA",skill="theme",prompt="Omar notices a classmate dropped crayons, so he stops to help pick them up. Which theme fits?",answer="Helping others is a kind choice.",hint="Think about the message shown by Omar’s action.",explanation="Omar chooses to help someone who needs it.",choices={"Crayons are difficult to carry.","Classrooms should have no colors.","Helping others is a kind choice."},tier="current",sourceFact="Verified Grade 2 skill: Theme",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="599222b635e54ad8e45114cef10161280df9dbae2341aeda342f985e1133b4b9",["evidenceHash"]="sha256:f793729ad77b5f02d13a644d34fc2a7f68ece2a4b9d3f1dd2072c2ef4785c72e",["sourceUrl"]="https://sites.google.com/view/abvmgr2/reading-work"},priority=1},
    {id="auto-theme-it-is-a-broad-lesson-that-can-apply-to-many-situations-e317f9",subject="Reading / ELA",skill="theme",prompt="Why is “Friends can solve problems by working together” a theme instead of a story detail?",answer="It is a broad lesson that can apply to many situations.",hint="Ask whether the idea could apply to another story.",explanation="Themes are broader messages, not single facts.",choices={"It tells exactly where the story happens.","It is a broad lesson that can apply to many situations.","It names one object in the story."},tier="current",sourceFact="Verified Grade 2 skill: Theme",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="599222b635e54ad8e45114cef10161280df9dbae2341aeda342f985e1133b4b9",["evidenceHash"]="sha256:f793729ad77b5f02d13a644d34fc2a7f68ece2a4b9d3f1dd2072c2ef4785c72e",["sourceUrl"]="https://sites.google.com/view/abvmgr2/reading-work"},priority=1},
    {id="auto-theme-it-states-a-lesson-shown-by-the-character-s-actions-08ae58",subject="Reading / ELA",skill="theme",prompt="Why is “Keep trying and learn from mistakes” a stronger theme than “Paper airplanes can fly”?",answer="It states a lesson shown by the character’s actions.",hint="Ask which choice could apply beyond this one story.",explanation="A theme is a broader lesson or message, not just a fact or detail from the story.",choices={"It states a lesson shown by the character’s actions.","It repeats one object from the story.","It describes only where the story happens."},tier="current",sourceFact="Verified Grade 2 skill: Theme",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="599222b635e54ad8e45114cef10161280df9dbae2341aeda342f985e1133b4b9",["evidenceHash"]="sha256:f793729ad77b5f02d13a644d34fc2a7f68ece2a4b9d3f1dd2072c2ef4785c72e",["sourceUrl"]="https://sites.google.com/view/abvmgr2/reading-work"},priority=1},
    {id="auto-theme-keep-trying-and-learn-from-mistakes-fa3d53",subject="Reading / ELA",skill="theme",prompt="Evan keeps changing one fold on his paper airplane until it finally flies. Which theme fits best?",answer="Keep trying and learn from mistakes.",hint="Choose the lesson shown by the whole situation.",explanation="Evan improves by continuing to try and learning from each attempt.",choices={"Only easy tasks are worth doing.","Stop after the first mistake.","Keep trying and learn from mistakes."},tier="current",sourceFact="Verified Grade 2 skill: Theme",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="599222b635e54ad8e45114cef10161280df9dbae2341aeda342f985e1133b4b9",["evidenceHash"]="sha256:f793729ad77b5f02d13a644d34fc2a7f68ece2a4b9d3f1dd2072c2ef4785c72e",["sourceUrl"]="https://sites.google.com/view/abvmgr2/reading-work"},priority=1},
    {id="auto-theme-kindness-can-help-people-feel-included-5c714b",subject="Reading / ELA",skill="theme",prompt="Nora sees a new student alone at recess and invites him to play. What theme fits best?",answer="Kindness can help people feel included.",hint="Choose the lesson shown by Nora’s action.",explanation="Nora’s kind action shows the message that including others matters.",choices={"Recess should always be quiet.","Kindness can help people feel included.","New students should play alone."},tier="current",sourceFact="Verified Grade 2 skill: Theme",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="599222b635e54ad8e45114cef10161280df9dbae2341aeda342f985e1133b4b9",["evidenceHash"]="sha256:f793729ad77b5f02d13a644d34fc2a7f68ece2a4b9d3f1dd2072c2ef4785c72e",["sourceUrl"]="https://sites.google.com/view/abvmgr2/reading-work"},priority=1},
    {id="auto-theme-practice-can-help-you-improve-6d7f66",subject="Reading / ELA",skill="theme",prompt="Lena practices tying her shoes each morning until she can do it alone. Which theme fits best?",answer="Practice can help you improve.",hint="Choose the lesson shown by the whole situation.",explanation="Lena improves because she keeps practicing.",choices={"Shoes should always be new.","Practice can help you improve.","Mornings are the longest part of the day."},tier="current",sourceFact="Verified Grade 2 skill: Theme",provenance={["kind"]="teacher-page",["sourceHash"]="teacher-pages-43dda9e1caba8dc64b2e",["captureHash"]="599222b635e54ad8e45114cef10161280df9dbae2341aeda342f985e1133b4b9",["evidenceHash"]="sha256:f793729ad77b5f02d13a644d34fc2a7f68ece2a4b9d3f1dd2072c2ef4785c72e",["sourceUrl"]="https://sites.google.com/view/abvmgr2/reading-work"},priority=1},
